// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/organizations", wrapper.ListOrganizations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/organizations/{organization_id}", wrapper.GetOrganization)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/contacts", wrapper.ListContacts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/books/v3/contacts", wrapper.CreateContact)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/contacts/{contact_id}", wrapper.GetContact)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/invoices", wrapper.ListInvoices)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/books/v3/invoices", wrapper.CreateInvoice)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/invoices/{invoice_id}", wrapper.GetInvoice)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/creditnotes", wrapper.ListCreditNotes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/creditnotes/{creditnote_id}", wrapper.GetCreditNote)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/customerpayments", wrapper.ListCustomerPayments)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/books/v3/customerpayments", wrapper.CreateCustomerPayment)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/books/v3/customerpayments/{payment_id}", wrapper.GetCustomerPayment)

	return m
}

