// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListContacts Lists contacts in the organization.
	// (GET /books/v3/contacts)
	ListContacts(ctx context.Context, request ListContactsRequestObject) (ListContactsResponseObject, error)
	// CreateContact Creates a contact.
	// (POST /books/v3/contacts)
	CreateContact(ctx context.Context, request CreateContactRequestObject) (CreateContactResponseObject, error)
	// GetContact Gets a contact.
	// (GET /books/v3/contacts/{contact_id})
	GetContact(ctx context.Context, request GetContactRequestObject) (GetContactResponseObject, error)
	// ListCreditNotes Lists credit notes in the organization.
	// (GET /books/v3/creditnotes)
	ListCreditNotes(ctx context.Context, request ListCreditNotesRequestObject) (ListCreditNotesResponseObject, error)
	// GetCreditNote Gets a credit note.
	// (GET /books/v3/creditnotes/{creditnote_id})
	GetCreditNote(ctx context.Context, request GetCreditNoteRequestObject) (GetCreditNoteResponseObject, error)
	// ListCustomerPayments Lists customer payments in the organization.
	// (GET /books/v3/customerpayments)
	ListCustomerPayments(ctx context.Context, request ListCustomerPaymentsRequestObject) (ListCustomerPaymentsResponseObject, error)
	// CreateCustomerPayment Records a customer payment. The payment is stored and returned by later reads.
	// (POST /books/v3/customerpayments)
	CreateCustomerPayment(ctx context.Context, request CreateCustomerPaymentRequestObject) (CreateCustomerPaymentResponseObject, error)
	// GetCustomerPayment Gets a customer payment, including the invoices it applies to.
	// (GET /books/v3/customerpayments/{payment_id})
	GetCustomerPayment(ctx context.Context, request GetCustomerPaymentRequestObject) (GetCustomerPaymentResponseObject, error)
	// ListInvoices Lists invoices in the organization.
	// (GET /books/v3/invoices)
	ListInvoices(ctx context.Context, request ListInvoicesRequestObject) (ListInvoicesResponseObject, error)
	// CreateInvoice Creates an invoice. The invoice is stored and returned by later reads.
	// (POST /books/v3/invoices)
	CreateInvoice(ctx context.Context, request CreateInvoiceRequestObject) (CreateInvoiceResponseObject, error)
	// GetInvoice Gets an invoice, including line items and notes.
	// (GET /books/v3/invoices/{invoice_id})
	GetInvoice(ctx context.Context, request GetInvoiceRequestObject) (GetInvoiceResponseObject, error)
	// ListOrganizations Lists Zoho Books organizations visible to the token.
	// (GET /books/v3/organizations)
	ListOrganizations(ctx context.Context, request ListOrganizationsRequestObject) (ListOrganizationsResponseObject, error)
	// GetOrganization Gets one Zoho Books organization.
	// (GET /books/v3/organizations/{organization_id})
	GetOrganization(ctx context.Context, request GetOrganizationRequestObject) (GetOrganizationResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
